pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: use the allowed caller
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(caller);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint256[] memory vals = new uint256[](1);
        vals[0] = 1;
        c.transfer(tos, vals);
        // Both versions leave 'from' unchanged and return true
        assertTrue(c.from() == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
    }
}

