pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a recipient and value
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234567890123456789012345678901234567890);
        uint[] memory values = new uint[](1);
        values[0] = 1;

        // Prank as the allowed sender
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        bool ok;
        try c.transfer(tos, values) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }

        // The reference version (using real from) returns true; the bug (using address(0)) returns false
        assertTrue(ok == true);
    }
}

