pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(caller);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vals = new uint[](1);
        vals[0] = 5;
        c.transfer(tos, vals);
        uint balanceAfter = address(c.caddress()).balance;
        // Reference: transfers 5 * 10^18 wei = 5 ether; Bug: transfers 5 wei
        // So correct balance > 0, buggy balance == 0 if caddress had no ether before
        assertTrue(balanceAfter > 0);
    }
}

